<div class="page-heading"><div><p class="eyebrow">SERIALIZED ASSET TRACKING</p><h1>Import equipment into the shop</h1><p class="text-secondary">Upload CSV, paste CSV, or paste manufacturer serial numbers. The entire import succeeds or fails together.</p></div></div>
<section class="card floating-card" data-card-key="inventory-import"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">upload_file</span>Import assets</h2><div class="card-body"><form action="/inventory/import" method="post" enctype="multipart/form-data" data-ajax-form><?= csrf() ?>
<label class="form-label">Item type<select class="form-select mb-3" name="item_type_id" required><option value="">Choose item type...</option><?php foreach ($types as $type): ?><option value="<?= e($type['id']) ?>"><?= e($type['name']) ?></option><?php endforeach; ?></select></label>
<label class="form-label">Paste format<select class="form-select mb-3" name="format"><option value="csv">CSV: asset_tag,serial_number</option><option value="text">Plain text: one serial number per line</option></select></label>
